item.content:encoded:
@media (max-width: 767px) {
  /* Quita el posicionamiento masonry y usa flex de 2 columnas */
  #product_wrapper.products {
    height: auto !important;
    display: flex !important;
    flex-wrap: wrap;
    margin-left: -5px !important;
    margin-right: -5px !important;
  }

  #product_wrapper .kad_product {
    position: relative !important;
    top: auto !important;
    left: auto !important;
    float: none !important;
    width: 50% !important;
    padding: 0 5px !important;
    margin-bottom: 15px;
  }

  /* Que la tarjeta y la imagen llenen toda la columna */
  #product_wrapper .grid_item,
  #product_wrapper .product_item,
  #product_wrapper .product_item a.product_item_link,
  #product_wrapper .product_item .kad-product-wrap {
    width: 100% !important;
  }
  #product_wrapper .product_item img {
    width: 100% !important;
    height: auto !important;
  }

  /* Texto legible */
  #product_wrapper .product_item .product_details h5 {
    font-size: 15px;
    line-height: 1.3;
  }
  #product_wrapper .product_item .button {
    font-size: 13px;
    padding: 8px 6px;
    width: 100%;
  }
}



/* Cuadrícula ordenada de productos (Virtue) */
#product_wrapper {
    display: flex !important;
    flex-wrap: wrap;
    height: auto !important;
}
#product_wrapper .grid_item,
#product_wrapper .product {
    position: relative !important;
    left: auto !important;
    top: auto !important;
    transform: none !important;
    float: none !important;
}
#product_wrapper .grid_item img {
    width: 100%;
    height: 220px;
    object-fit: contain;
}
#product_wrapper .grid_item h5 {
    min-height: 3em;
}
